import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '360px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="you@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        helperText="Присылаем письма не чаще раза в неделю"
      />
      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>
      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="bottom-right"
      />
    </form>
  );
}

